window.MCAT_BANK = {"meta": {"version": 1, "disclaimer": "Original practice items for education; not AAMC material.", "sections": ["CP", "CARS", "BB", "PS"], "brand": "MCAT Prep · College Path", "title": "MCAT Prep Practice"}, "questions": [{"id": "cp-001", "section": "CP", "topic": "enzyme-kinetics", "difficulty": 2, "passage": null, "stem": "An enzyme-catalyzed reaction follows Michaelis–Menten kinetics. Doubling [S] when [S] ≪ Km most nearly:", "choices": ["A) Doubles the initial rate", "B) Halves the initial rate", "C) Leaves Vmax unchanged but halves Km", "D) Doubles Vmax"], "answer": 0, "explain": "When [S] ≪ Km, v ≈ (Vmax/Km)[S], so rate is approximately linear in [S]. Doubling [S] ≈ doubles v. Vmax and Km are constants for a given enzyme/condition.", "tags": ["high-frequency", "kinetics"]}, {"id": "cp-002", "section": "CP", "topic": "enzyme-kinetics", "difficulty": 3, "passage": null, "stem": "A competitive inhibitor increases the apparent Km of an enzyme but does not change Vmax. Which statement is most accurate?", "choices": ["A) The inhibitor binds only the ES complex", "B) Sufficient substrate can overcome the inhibition at saturating [S]", "C) The inhibitor covalently modifies the active site", "D) kcat must decrease"], "answer": 1, "explain": "Competitive inhibitors compete for free enzyme. At high [S], substrate outcompetes inhibitor, so Vmax is unchanged while apparent Km rises.", "tags": ["high-frequency"]}, {"id": "cp-003", "section": "CP", "topic": "enzyme-kinetics", "difficulty": 3, "passage": null, "stem": "In Lineweaver–Burk plots, a noncompetitive inhibitor that decreases Vmax without changing Km intersects the uninhibited line on the:", "choices": ["A) x-axis (same −1/Km)", "B) y-axis (same 1/Vmax)", "C) origin only", "D) positive x-axis only"], "answer": 0, "explain": "Pure noncompetitive inhibition: same Km (same x-intercept −1/Km), higher 1/Vmax (higher y-intercept). Lines meet on the x-axis.", "tags": ["high-frequency"]}, {"id": "cp-004", "section": "CP", "topic": "amino-acids", "difficulty": 1, "passage": null, "stem": "Which amino acid side chain is most likely negatively charged at physiological pH (~7.4)?", "choices": ["A) Lysine", "B) Aspartate", "C) Asparagine", "D) Histidine"], "answer": 1, "explain": "Aspartate (and glutamate) have carboxylic acid side chains with pKa ≈ 4, so they are deprotonated (−) at pH 7.4. Lys is (+); Asn is polar uncharged; His is often near-neutral/partially protonated.", "tags": ["high-frequency", "amino-acids"]}, {"id": "cp-005", "section": "CP", "topic": "amino-acids", "difficulty": 2, "passage": null, "stem": "Which amino acid is most associated with disrupting α-helix geometry in transmembrane segments?", "choices": ["A) Alanine", "B) Leucine", "C) Proline", "D) Methionine"], "answer": 2, "explain": "Proline’s cyclic secondary amine constrains backbone φ and lacks an amide H-bond donor, commonly kinking or breaking helices.", "tags": ["high-frequency"]}, {"id": "cp-006", "section": "CP", "topic": "amino-acids", "difficulty": 2, "passage": null, "stem": "At pH 1, which form best describes the predominant charge state of free glycine?", "choices": ["A) Net −1", "B) Net 0 (zwitterion)", "C) Net +1", "D) Net +2"], "answer": 2, "explain": "At very low pH both the α-COOH and α-NH3+ are protonated: COOH (0) + NH3+ (+1) → net +1.", "tags": ["high-frequency"]}, {"id": "cp-007", "section": "CP", "topic": "thermodynamics", "difficulty": 2, "passage": null, "stem": "A reaction has ΔG°′ < 0. Under cellular conditions ΔG can still be positive if:", "choices": ["A) The reaction is catalyzed by an enzyme", "B) Q is sufficiently large that RT ln Q outweighs ΔG°′", "C) Temperature is absolute zero", "D) The reaction produces ATP"], "answer": 1, "explain": "ΔG = ΔG°′ + RT ln Q. A large mass-action ratio Q can make ΔG positive even when ΔG°′ is negative.", "tags": ["high-frequency"]}, {"id": "cp-008", "section": "CP", "topic": "acids-bases", "difficulty": 2, "passage": null, "stem": "A buffer is most effective when:", "choices": ["A) pH = pKa ± ~1 and both HA and A− are present", "B) Only strong acid is present", "C) pH ≫ pKa + 3 with no conjugate base", "D) The solution is pure water"], "answer": 0, "explain": "Henderson–Hasselbalch: buffering capacity peaks near pKa when both members of the conjugate pair are appreciable.", "tags": ["high-frequency"]}, {"id": "cp-009", "section": "CP", "topic": "electrochemistry", "difficulty": 3, "passage": null, "stem": "For the half-reaction Cu2+ + 2e− → Cu, E° = +0.34 V. Increasing [Cu2+] at constant T tends to:", "choices": ["A) Decrease E for the half-cell (Nernst)", "B) Increase E for the half-cell", "C) Leave E unchanged always", "D) Reverse the sign of E°"], "answer": 1, "explain": "Nernst: E = E° − (RT/nF) ln(1/[Cu2+]). Higher [Cu2+] makes ln term smaller (more negative argument magnitude decreases), so E increases.", "tags": ["circuits-fluids", "electrochem"]}, {"id": "cp-010", "section": "CP", "topic": "circuits", "difficulty": 2, "passage": null, "stem": "Two resistors R and 2R are in series with a battery of emf ε (ideal). The voltage across 2R is:", "choices": ["A) ε/3", "B) 2ε/3", "C) ε", "D) ε/2"], "answer": 1, "explain": "Series current I = ε/(3R). V_{2R} = I·2R = 2ε/3.", "tags": ["high-frequency", "circuits"]}, {"id": "cp-011", "section": "CP", "topic": "circuits", "difficulty": 2, "passage": null, "stem": "Capacitors C and 2C in parallel have equivalent capacitance:", "choices": ["A) (2/3)C", "B) 3C", "C) (1/2)C", "D) C"], "answer": 1, "explain": "Parallel capacitors add: C_eq = C + 2C = 3C.", "tags": ["circuits"]}, {"id": "cp-012", "section": "CP", "topic": "fluids", "difficulty": 2, "passage": null, "stem": "Ideal incompressible flow in a horizontal pipe narrows. Continuity and Bernoulli imply that in the constriction:", "choices": ["A) Speed decreases and pressure increases", "B) Speed increases and pressure decreases", "C) Speed and pressure both increase", "D) Density must decrease"], "answer": 1, "explain": "A1v1 = A2v2 → smaller A ⇒ higher v. Bernoulli: higher speed ⇒ lower pressure (horizontal).", "tags": ["high-frequency", "fluids"]}, {"id": "cp-013", "section": "CP", "topic": "fluids", "difficulty": 3, "passage": null, "stem": "Blood flow is often modeled as laminar. Doubling vessel radius (other factors fixed) changes Poiseuille flow rate by a factor of:", "choices": ["A) 2", "B) 4", "C) 8", "D) 16"], "answer": 3, "explain": "Q ∝ r^4, so 2^4 = 16.", "tags": ["fluids", "high-frequency"]}, {"id": "cp-014", "section": "CP", "topic": "optics", "difficulty": 2, "passage": null, "stem": "A converging lens forms a real inverted image. Object distance u and focal length f satisfy:", "choices": ["A) u < f", "B) u = f", "C) u > f", "D) u must be negative in all sign conventions"], "answer": 2, "explain": "For a converging lens, real images form when the object is outside the focal length (u > f in the usual thin-lens magnitude discussion).", "tags": ["optics"]}, {"id": "cp-015", "section": "CP", "topic": "optics", "difficulty": 2, "passage": null, "stem": "Snell’s law: light goes from n=1.00 to n=1.33. If θ1 = 30°, sin θ2 is closest to:", "choices": ["A) 0.50", "B) 0.38", "C) 0.75", "D) 1.00"], "answer": 1, "explain": "n1 sin θ1 = n2 sin θ2 → sin θ2 = (1.00/1.33) sin 30° ≈ 0.75/1.33 ≈ 0.376.", "tags": ["optics"]}, {"id": "cp-016", "section": "CP", "topic": "nuclear", "difficulty": 2, "passage": null, "stem": "Beta-minus decay of a nucleus increases the atomic number by 1 because:", "choices": ["A) A proton converts to a neutron emitting e+", "B) A neutron converts to a proton emitting e− and antineutrino", "C) An alpha particle is emitted", "D) Electron capture removes a proton"], "answer": 1, "explain": "β−: n → p + e− + ν̄e, Z increases by 1, A unchanged.", "tags": ["nuclear"]}, {"id": "cp-017", "section": "CP", "topic": "stoichiometry", "difficulty": 2, "passage": null, "stem": "Complete combustion of 1 mol C3H8 produces how many moles of CO2?", "choices": ["A) 1", "B) 3", "C) 4", "D) 8"], "answer": 1, "explain": "C3H8 + 5 O2 → 3 CO2 + 4 H2O.", "tags": ["chem"]}, {"id": "cp-018", "section": "CP", "topic": "equilibrium", "difficulty": 3, "passage": null, "stem": "For N2 + 3 H2 ⇌ 2 NH3, increasing pressure at constant T (by volume decrease) shifts equilibrium:", "choices": ["A) Toward reactants (fewer moles gas on left)", "B) Toward products (fewer moles gas on right)", "C) No shift for gas reactions", "D) Always to the endothermic side only"], "answer": 1, "explain": "4 mol gas → 2 mol gas; higher P favors fewer moles → products.", "tags": ["equilibrium"]}, {"id": "cp-019", "section": "CP", "topic": "kinetics-chem", "difficulty": 2, "passage": null, "stem": "A first-order half-life is 20 min. After 60 min, the fraction of reactant remaining is:", "choices": ["A) 1/2", "B) 1/4", "C) 1/8", "D) 1/16"], "answer": 2, "explain": "Three half-lives: (1/2)^3 = 1/8.", "tags": ["kinetics"]}, {"id": "cp-020", "section": "CP", "topic": "electrostatics", "difficulty": 2, "passage": null, "stem": "Two point charges +q and +q separated by r. If r is doubled, Coulomb force magnitude becomes:", "choices": ["A) 4×", "B) 2×", "C) 1/2", "D) 1/4"], "answer": 3, "explain": "F ∝ 1/r^2 → (1/2)^2 = 1/4.", "tags": ["circuits-fluids"]}, {"id": "cp-021", "section": "CP", "topic": "waves", "difficulty": 2, "passage": null, "stem": "Sound intensity level increases by 10 dB. Intensity multiplies by approximately:", "choices": ["A) 2", "B) 10", "C) 100", "D) √10"], "answer": 1, "explain": "Δβ = 10 log10(I2/I1); +10 dB ⇒ I2/I1 = 10.", "tags": ["waves"]}, {"id": "cp-022", "section": "CP", "topic": "thermodynamics", "difficulty": 3, "passage": null, "stem": "An ideal gas expands isothermally. Which is true?", "choices": ["A) ΔU = 0 and Q = −W (convention: W work by system)", "B) ΔU > 0 always", "C) Q = 0", "D) W = 0"], "answer": 0, "explain": "For ideal gas, U depends only on T → isothermal ΔU = 0 ⇒ Q = W (by system) in common physics convention.", "tags": ["thermo"]}, {"id": "cp-023", "section": "CP", "topic": "solutions", "difficulty": 2, "passage": null, "stem": "Which aqueous solution has the highest boiling-point elevation (ideal, same molality of particles)?", "choices": ["A) 1 m glucose", "B) 1 m NaCl", "C) 1 m CaCl2", "D) Pure water"], "answer": 2, "explain": "i ≈ 3 for CaCl2 → most particles → largest ΔTb = i·Kb·m.", "tags": ["colligative"]}, {"id": "cp-024", "section": "CP", "topic": "organic", "difficulty": 2, "passage": null, "stem": "An SN1 reaction rate depends primarily on:", "choices": ["A) Nucleophile concentration only", "B) Substrate concentration (carbocation formation RDS)", "C) Only solvent polarity with zero [substrate] dependence", "D) Only the leaving-group concentration in product"], "answer": 1, "explain": "SN1 rate ≈ k[substrate]; nucleophile attacks after RDS carbocation formation.", "tags": ["orgo"]}, {"id": "cp-025", "section": "CP", "topic": "organic", "difficulty": 3, "passage": null, "stem": "Which functional group is most readily reduced by LiAlH4 to a primary alcohol?", "choices": ["A) Alkene", "B) Carboxylic acid", "C) Ether", "D) Tertiary amine"], "answer": 1, "explain": "LiAlH4 reduces carboxylic acids (and esters) to primary alcohols; alkenes typically need catalytic hydrogenation.", "tags": ["orgo"]}, {"id": "cp-026", "section": "CP", "topic": "amino-acids", "difficulty": 3, "passage": null, "stem": "The isoelectric point (pI) of a simple amino acid is approximately the average of:", "choices": ["A) All side-chain pKa values only", "B) The two pKa values that bound the zwitterion net-zero form", "C) pH 7 always", "D) Melting point and boiling point"], "answer": 1, "explain": "pI ≈ average of the pKa values flanking the zwitterionic (net zero) form.", "tags": ["amino-acids", "high-frequency"]}, {"id": "cp-027", "section": "CP", "topic": "enzyme-kinetics", "difficulty": 4, "passage": null, "stem": "kcat for an enzyme is 100 s−1 and Km is 2 mM. Catalytic efficiency kcat/Km equals:", "choices": ["A) 50 M−1 s−1", "B) 5×10^4 M−1 s−1", "C) 200 s−1", "D) 0.02 mM s"], "answer": 1, "explain": "2 mM = 0.002 M; 100 / 0.002 = 5×10^4 M−1 s−1.", "tags": ["kinetics"]}, {"id": "cp-028", "section": "CP", "topic": "fluids", "difficulty": 2, "passage": null, "stem": "Gauge pressure at depth h in an incompressible fluid is:", "choices": ["A) ρgh", "B) ρg/h", "C) P_atm only", "D) mgh"], "answer": 0, "explain": "P_gauge = ρgh for static fluid.", "tags": ["fluids"]}, {"id": "cars-001", "section": "CARS", "topic": "reasoning-within", "difficulty": 2, "passage": "Municipal libraries have quietly become hybrid civic hubs: not only book lenders but also job-search terminals, tax-help desks, and cooling centers during heat waves. Critics argue that mission creep dilutes the library’s core purpose of literacy. Defenders reply that literacy itself is inseparable from the material conditions that let people read—stable housing, internet access, and time. When a library offers résumé workshops, it is not abandoning books; it is removing barriers that make books unreachable. The sharper debate is fiscal. City budgets treat libraries as discretionary amenities rather than as infrastructure. Infrastructure framing would change maintenance standards, staffing formulas, and resilience planning. A flooded basement that ruins archives is then not a cultural misfortune but a systems failure. Whether councils accept that reframing may determine whether libraries remain open long enough for the literacy mission to matter.", "stem": "According to the passage, defenders of library workshops primarily claim that such programs:", "choices": ["A) Replace literacy with job training as the library’s sole goal", "B) Address conditions that otherwise block access to literacy", "C) Prove that books are obsolete", "D) Should be funded only by private donors"], "answer": 1, "explain": "Defenders say literacy depends on material conditions; workshops remove barriers that make books unreachable.", "tags": ["high-frequency"]}, {"id": "cars-002", "section": "CARS", "topic": "reasoning-beyond", "difficulty": 3, "passage": "Municipal libraries have quietly become hybrid civic hubs: not only book lenders but also job-search terminals, tax-help desks, and cooling centers during heat waves. Critics argue that mission creep dilutes the library’s core purpose of literacy. Defenders reply that literacy itself is inseparable from the material conditions that let people read—stable housing, internet access, and time. When a library offers résumé workshops, it is not abandoning books; it is removing barriers that make books unreachable. The sharper debate is fiscal. City budgets treat libraries as discretionary amenities rather than as infrastructure. Infrastructure framing would change maintenance standards, staffing formulas, and resilience planning. A flooded basement that ruins archives is then not a cultural misfortune but a systems failure. Whether councils accept that reframing may determine whether libraries remain open long enough for the literacy mission to matter.", "stem": "The author’s phrase “infrastructure framing” most nearly suggests treating libraries as:", "choices": ["A) Optional cultural extras", "B) Systems whose failure modes deserve planning standards", "C) For-profit startups", "D) Replacements for hospitals"], "answer": 1, "explain": "Infrastructure framing implies maintenance standards, staffing formulas, resilience—not discretionary amenities.", "tags": ["high-frequency"]}, {"id": "cars-003", "section": "CARS", "topic": "reasoning-within", "difficulty": 2, "passage": "Municipal libraries have quietly become hybrid civic hubs: not only book lenders but also job-search terminals, tax-help desks, and cooling centers during heat waves. Critics argue that mission creep dilutes the library’s core purpose of literacy. Defenders reply that literacy itself is inseparable from the material conditions that let people read—stable housing, internet access, and time. When a library offers résumé workshops, it is not abandoning books; it is removing barriers that make books unreachable. The sharper debate is fiscal. City budgets treat libraries as discretionary amenities rather than as infrastructure. Infrastructure framing would change maintenance standards, staffing formulas, and resilience planning. A flooded basement that ruins archives is then not a cultural misfortune but a systems failure. Whether councils accept that reframing may determine whether libraries remain open long enough for the literacy mission to matter.", "stem": "The passage implies that calling a flooded library basement only a “cultural misfortune”:", "choices": ["A) Adequately funds repairs", "B) Understates a preventable systems failure under infrastructure logic", "C) Celebrates archives", "D) Is the author’s preferred framing"], "answer": 1, "explain": "Author contrasts cultural misfortune with systems failure under infrastructure framing.", "tags": ["high-frequency"]}, {"id": "cars-004", "section": "CARS", "topic": "main-idea", "difficulty": 2, "passage": "Municipal libraries have quietly become hybrid civic hubs: not only book lenders but also job-search terminals, tax-help desks, and cooling centers during heat waves. Critics argue that mission creep dilutes the library’s core purpose of literacy. Defenders reply that literacy itself is inseparable from the material conditions that let people read—stable housing, internet access, and time. When a library offers résumé workshops, it is not abandoning books; it is removing barriers that make books unreachable. The sharper debate is fiscal. City budgets treat libraries as discretionary amenities rather than as infrastructure. Infrastructure framing would change maintenance standards, staffing formulas, and resilience planning. A flooded basement that ruins archives is then not a cultural misfortune but a systems failure. Whether councils accept that reframing may determine whether libraries remain open long enough for the literacy mission to matter.", "stem": "The central tension in the passage is best captured as:", "choices": ["A) Print vs digital catalogs", "B) Mission breadth and budget category vs literacy aims", "C) Teachers vs librarians", "D) Federal vs state copyright"], "answer": 1, "explain": "Mission creep debate plus fiscal category (amenity vs infrastructure) around literacy purpose.", "tags": ["high-frequency"]}, {"id": "cars-005", "section": "CARS", "topic": "reasoning-within", "difficulty": 2, "passage": "Historians of technology sometimes overstate discontinuity. The printing press did not instantly create mass literacy; it interacted with paper prices, urban density, religious incentives, and schooling. Likewise, today’s generative models do not automatically produce a new epistemology. They amplify existing incentives: speed over verification, fluency over sourcing, engagement over accuracy. Institutions that already rewarded careful citation may use the tools as drafts to be checked. Institutions that already rewarded volume may use them as substitutes for thought. The machine, in this view, is a mirror with a motor—reflecting norms while accelerating whichever ones are already funded.", "stem": "In the technology passage, the printing-press analogy primarily functions to:", "choices": ["A) Prove generative models are identical to presses", "B) Caution against treating tools as automatic historical ruptures", "C) Argue paper prices no longer matter", "D) Deny that tools change anything"], "answer": 1, "explain": "Author says discontinuity is overstated; tools interact with incentives and institutions.", "tags": ["high-frequency"]}, {"id": "cars-006", "section": "CARS", "topic": "reasoning-within", "difficulty": 3, "passage": "Historians of technology sometimes overstate discontinuity. The printing press did not instantly create mass literacy; it interacted with paper prices, urban density, religious incentives, and schooling. Likewise, today’s generative models do not automatically produce a new epistemology. They amplify existing incentives: speed over verification, fluency over sourcing, engagement over accuracy. Institutions that already rewarded careful citation may use the tools as drafts to be checked. Institutions that already rewarded volume may use them as substitutes for thought. The machine, in this view, is a mirror with a motor—reflecting norms while accelerating whichever ones are already funded.", "stem": "“A mirror with a motor” most nearly means generative models:", "choices": ["A) Only reflect without changing pace", "B) Reflect existing norms while speeding them up", "C) Invent entirely new moral systems overnight", "D) Eliminate institutional incentives"], "answer": 1, "explain": "Mirror = reflect norms; motor = accelerate funded incentives.", "tags": ["high-frequency"]}, {"id": "cars-007", "section": "CARS", "topic": "inference", "difficulty": 3, "passage": "Historians of technology sometimes overstate discontinuity. The printing press did not instantly create mass literacy; it interacted with paper prices, urban density, religious incentives, and schooling. Likewise, today’s generative models do not automatically produce a new epistemology. They amplify existing incentives: speed over verification, fluency over sourcing, engagement over accuracy. Institutions that already rewarded careful citation may use the tools as drafts to be checked. Institutions that already rewarded volume may use them as substitutes for thought. The machine, in this view, is a mirror with a motor—reflecting norms while accelerating whichever ones are already funded.", "stem": "Which institutional behavior would the author most expect where volume is already rewarded?", "choices": ["A) Using models only after exhaustive citation checks", "B) Substituting model output for careful thought", "C) Banning all drafting tools", "D) Ignoring engagement metrics"], "answer": 1, "explain": "Institutions rewarding volume may use tools as substitutes for thought.", "tags": ["high-frequency"]}, {"id": "cars-008", "section": "CARS", "topic": "main-idea", "difficulty": 2, "passage": "Historians of technology sometimes overstate discontinuity. The printing press did not instantly create mass literacy; it interacted with paper prices, urban density, religious incentives, and schooling. Likewise, today’s generative models do not automatically produce a new epistemology. They amplify existing incentives: speed over verification, fluency over sourcing, engagement over accuracy. Institutions that already rewarded careful citation may use the tools as drafts to be checked. Institutions that already rewarded volume may use them as substitutes for thought. The machine, in this view, is a mirror with a motor—reflecting norms while accelerating whichever ones are already funded.", "stem": "The author’s primary claim is that generative tools:", "choices": ["A) Guarantee better epistemology", "B) Amplify whichever incentives institutions already fund", "C) Have no interaction with social context", "D) Make verification obsolete"], "answer": 1, "explain": "Tools amplify existing incentives; institutions shape use.", "tags": ["high-frequency"]}, {"id": "cars-009", "section": "CARS", "topic": "reasoning-within", "difficulty": 2, "passage": "Public health messaging often assumes that information deficits explain behavior. Tell people the risks, and choices will follow. Behavioral research complicates that story. Identity, peer norms, and distrust of messengers can outweigh factual updates. A campaign that is statistically accurate yet socially tone-deaf may harden resistance. Effective communication therefore treats audiences as members of communities with histories, not as empty vessels. This does not mean abandoning evidence; it means packaging evidence inside relationships that can carry it.", "stem": "The public-health passage challenges the idea that:", "choices": ["A) Evidence should ever be used", "B) Information deficits alone explain behavior", "C) Peer norms exist", "D) Messengers matter less than facts always"], "answer": 1, "explain": "Opening criticizes information-deficit model of behavior change.", "tags": ["high-frequency"]}, {"id": "cars-010", "section": "CARS", "topic": "reasoning-beyond", "difficulty": 3, "passage": "Public health messaging often assumes that information deficits explain behavior. Tell people the risks, and choices will follow. Behavioral research complicates that story. Identity, peer norms, and distrust of messengers can outweigh factual updates. A campaign that is statistically accurate yet socially tone-deaf may harden resistance. Effective communication therefore treats audiences as members of communities with histories, not as empty vessels. This does not mean abandoning evidence; it means packaging evidence inside relationships that can carry it.", "stem": "A “statistically accurate yet socially tone-deaf” campaign fails, per the author, because:", "choices": ["A) Statistics are never useful", "B) Identity, norms, and distrust can outweigh factual updates", "C) Audiences prefer falsehoods exclusively", "D) Only entertainment works"], "answer": 1, "explain": "Behavioral factors can outweigh factual updates; tone-deaf accuracy may harden resistance.", "tags": ["high-frequency"]}, {"id": "cars-011", "section": "CARS", "topic": "main-idea", "difficulty": 2, "passage": "Public health messaging often assumes that information deficits explain behavior. Tell people the risks, and choices will follow. Behavioral research complicates that story. Identity, peer norms, and distrust of messengers can outweigh factual updates. A campaign that is statistically accurate yet socially tone-deaf may harden resistance. Effective communication therefore treats audiences as members of communities with histories, not as empty vessels. This does not mean abandoning evidence; it means packaging evidence inside relationships that can carry it.", "stem": "Effective communication, in the author’s view, requires:", "choices": ["A) Abandoning evidence", "B) Treating audiences as community members with histories", "C) Longer pamphlets only", "D) Avoiding relationships"], "answer": 1, "explain": "Package evidence inside relationships; audiences aren’t empty vessels.", "tags": ["high-frequency"]}, {"id": "cars-012", "section": "CARS", "topic": "definition", "difficulty": 2, "passage": "In ethics of clinical research, equipoise refers to genuine uncertainty within the expert community about which intervention is superior. Without equipoise, randomly assigning patients can look like withholding known better care. Yet equipoise is contested: must every individual clinician be uncertain, or is community uncertainty enough? Strict individual equipoise would stall many trials; pure community equipoise can ask clinicians to act against their own best judgment. The compromise practiced in many IRBs is messy but operational: require community uncertainty, disclose conflicts, and monitor emerging data so that trials stop when uncertainty collapses.", "stem": "In the research-ethics passage, equipoise refers to:", "choices": ["A) Guaranteed benefit for every participant", "B) Genuine uncertainty about which intervention is superior", "C) Equal funding of all labs", "D) Patient payment equity"], "answer": 1, "explain": "Defined as genuine uncertainty about superiority.", "tags": ["high-frequency"]}, {"id": "cars-013", "section": "CARS", "topic": "reasoning-within", "difficulty": 3, "passage": "In ethics of clinical research, equipoise refers to genuine uncertainty within the expert community about which intervention is superior. Without equipoise, randomly assigning patients can look like withholding known better care. Yet equipoise is contested: must every individual clinician be uncertain, or is community uncertainty enough? Strict individual equipoise would stall many trials; pure community equipoise can ask clinicians to act against their own best judgment. The compromise practiced in many IRBs is messy but operational: require community uncertainty, disclose conflicts, and monitor emerging data so that trials stop when uncertainty collapses.", "stem": "A problem with strict individual clinician equipoise, according to the passage, is that it:", "choices": ["A) Speeds every trial", "B) Could stall many trials", "C) Eliminates IRBs", "D) Requires hiding conflicts"], "answer": 1, "explain": "Strict individual equipoise would stall many trials.", "tags": ["high-frequency"]}, {"id": "cars-014", "section": "CARS", "topic": "inference", "difficulty": 3, "passage": "In ethics of clinical research, equipoise refers to genuine uncertainty within the expert community about which intervention is superior. Without equipoise, randomly assigning patients can look like withholding known better care. Yet equipoise is contested: must every individual clinician be uncertain, or is community uncertainty enough? Strict individual equipoise would stall many trials; pure community equipoise can ask clinicians to act against their own best judgment. The compromise practiced in many IRBs is messy but operational: require community uncertainty, disclose conflicts, and monitor emerging data so that trials stop when uncertainty collapses.", "stem": "The “messy but operational” IRB compromise includes:", "choices": ["A) Ignoring emerging data", "B) Community uncertainty, disclosure, and stopping when uncertainty collapses", "C) Forbidding randomization always", "D) Requiring every clinician’s personal doubt forever"], "answer": 1, "explain": "Community uncertainty, disclose conflicts, monitor data to stop when uncertainty collapses.", "tags": ["high-frequency"]}, {"id": "cars-015", "section": "CARS", "topic": "reasoning-within", "difficulty": 2, "passage": "Urban soundscapes are rarely designed; they accumulate. Traffic hum, HVAC drone, and delivery trucks form a baseline that residents stop noticing until illness or remote work forces attention. Noise is not merely annoyance—chronic exposure correlates with cardiovascular stress markers. Zoning that separates industrial and residential uses was partly a noise policy in disguise. As mixed-use density returns, cities rediscover that quiet is a scarce public good. The policy puzzle is distributional: who gets the quiet block, and who gets the freight corridor?", "stem": "The soundscape passage suggests noise became newly salient for some residents because of:", "choices": ["A) Lower traffic nationwide", "B) Illness or remote work forcing attention", "C) Elimination of HVAC", "D) Universal silence ordinances"], "answer": 1, "explain": "Baseline unnoticed until illness or remote work forces attention.", "tags": ["high-frequency"]}, {"id": "cars-016", "section": "CARS", "topic": "inference", "difficulty": 3, "passage": "Urban soundscapes are rarely designed; they accumulate. Traffic hum, HVAC drone, and delivery trucks form a baseline that residents stop noticing until illness or remote work forces attention. Noise is not merely annoyance—chronic exposure correlates with cardiovascular stress markers. Zoning that separates industrial and residential uses was partly a noise policy in disguise. As mixed-use density returns, cities rediscover that quiet is a scarce public good. The policy puzzle is distributional: who gets the quiet block, and who gets the freight corridor?", "stem": "Calling quiet a “scarce public good” most strongly implies:", "choices": ["A) Quiet has no health relevance", "B) Allocation and distribution of quiet raise fairness questions", "C) Only private yards matter", "D) Freight corridors are costless"], "answer": 1, "explain": "Scarce public good + distributional puzzle: who gets quiet vs freight.", "tags": ["high-frequency"]}, {"id": "cars-017", "section": "CARS", "topic": "reasoning-within", "difficulty": 2, "passage": "Urban soundscapes are rarely designed; they accumulate. Traffic hum, HVAC drone, and delivery trucks form a baseline that residents stop noticing until illness or remote work forces attention. Noise is not merely annoyance—chronic exposure correlates with cardiovascular stress markers. Zoning that separates industrial and residential uses was partly a noise policy in disguise. As mixed-use density returns, cities rediscover that quiet is a scarce public good. The policy puzzle is distributional: who gets the quiet block, and who gets the freight corridor?", "stem": "Zoning that separated industrial and residential uses is described as:", "choices": ["A) Unrelated to noise", "B) Partly a noise policy in disguise", "C) Purely aesthetic", "D) Abolishing mixed-use forever without tradeoffs"], "answer": 1, "explain": "Explicitly “partly a noise policy in disguise.”", "tags": ["high-frequency"]}, {"id": "cars-018", "section": "CARS", "topic": "main-idea", "difficulty": 2, "passage": "Urban soundscapes are rarely designed; they accumulate. Traffic hum, HVAC drone, and delivery trucks form a baseline that residents stop noticing until illness or remote work forces attention. Noise is not merely annoyance—chronic exposure correlates with cardiovascular stress markers. Zoning that separates industrial and residential uses was partly a noise policy in disguise. As mixed-use density returns, cities rediscover that quiet is a scarce public good. The policy puzzle is distributional: who gets the quiet block, and who gets the freight corridor?", "stem": "Overall, the soundscape passage argues that:", "choices": ["A) Noise is only annoyance without physiology", "B) Accumulated urban noise has health and equity stakes as density mixes uses", "C) Cities should ban all trucks immediately without tradeoffs", "D) Remote work eliminates noise policy"], "answer": 1, "explain": "Noise accumulates, has health correlates, and mixed-use revives distributional quiet questions.", "tags": ["high-frequency"]}, {"id": "cars-019", "section": "CARS", "topic": "reasoning-within", "difficulty": 2, "passage": "Municipal libraries have quietly become hybrid civic hubs: not only book lenders but also job-search terminals, tax-help desks, and cooling centers during heat waves. Critics argue that mission creep dilutes the library’s core purpose of literacy. Defenders reply that literacy itself is inseparable from the material conditions that let people read—stable housing, internet access, and time. When a library offers résumé workshops, it is not abandoning books; it is removing barriers that make books unreachable. The sharper debate is fiscal. City budgets treat libraries as discretionary amenities rather than as infrastructure. Infrastructure framing would change maintenance standards, staffing formulas, and resilience planning. A flooded basement that ruins archives is then not a cultural misfortune but a systems failure. Whether councils accept that reframing may determine whether libraries remain open long enough for the literacy mission to matter.", "stem": "The author’s attitude toward “mission creep” critics is best described as:", "choices": ["A) Fully endorsing that workshops abandon literacy", "B) Presenting their view then privileging the defenders’ conditions argument and fiscal reframing", "C) Ignoring critics", "D) Demanding libraries close"], "answer": 1, "explain": "Critics are stated; defenders get the substantive reply; author pushes infrastructure framing.", "tags": ["high-frequency"]}, {"id": "cars-020", "section": "CARS", "topic": "structure", "difficulty": 3, "passage": "Historians of technology sometimes overstate discontinuity. The printing press did not instantly create mass literacy; it interacted with paper prices, urban density, religious incentives, and schooling. Likewise, today’s generative models do not automatically produce a new epistemology. They amplify existing incentives: speed over verification, fluency over sourcing, engagement over accuracy. Institutions that already rewarded careful citation may use the tools as drafts to be checked. Institutions that already rewarded volume may use them as substitutes for thought. The machine, in this view, is a mirror with a motor—reflecting norms while accelerating whichever ones are already funded.", "stem": "Which best describes the organization of the technology passage?", "choices": ["A) Strict chronological history of computing", "B) Analogy to past tech, then claim about amplification of incentives, then institutional contrast", "C) List of model architectures", "D) Pure memoir"], "answer": 1, "explain": "Press analogy → models amplify incentives → institutions that reward care vs volume.", "tags": ["high-frequency"]}, {"id": "cars-021", "section": "CARS", "topic": "weaken", "difficulty": 4, "passage": "Public health messaging often assumes that information deficits explain behavior. Tell people the risks, and choices will follow. Behavioral research complicates that story. Identity, peer norms, and distrust of messengers can outweigh factual updates. A campaign that is statistically accurate yet socially tone-deaf may harden resistance. Effective communication therefore treats audiences as members of communities with histories, not as empty vessels. This does not mean abandoning evidence; it means packaging evidence inside relationships that can carry it.", "stem": "Which finding would most weaken the public-health author’s skepticism of information-deficit models?", "choices": ["A) In a randomized trial, purely factual flyers changed behavior as much as norm-based messages across distrusting groups", "B) Celebrities sell products", "C) Some people distrust officials", "D) Pamphlets can be long"], "answer": 0, "explain": "If bare facts work equally well even amid distrust, the critique of information-deficit models is weakened.", "tags": ["high-frequency"]}, {"id": "cars-022", "section": "CARS", "topic": "strengthen", "difficulty": 3, "passage": "In ethics of clinical research, equipoise refers to genuine uncertainty within the expert community about which intervention is superior. Without equipoise, randomly assigning patients can look like withholding known better care. Yet equipoise is contested: must every individual clinician be uncertain, or is community uncertainty enough? Strict individual equipoise would stall many trials; pure community equipoise can ask clinicians to act against their own best judgment. The compromise practiced in many IRBs is messy but operational: require community uncertainty, disclose conflicts, and monitor emerging data so that trials stop when uncertainty collapses.", "stem": "Which evidence would most strengthen the equipoise passage’s concern about individual equipoise?", "choices": ["A) Survey: most clinicians personally favor one arm yet community guidelines remain split", "B) All clinicians agree always", "C) Trials never stop early", "D) IRBs never meet"], "answer": 0, "explain": "Personal certainty amid community split shows tension the passage describes.", "tags": ["high-frequency"]}, {"id": "cars-023", "section": "CARS", "topic": "analogy", "difficulty": 3, "passage": "Municipal libraries have quietly become hybrid civic hubs: not only book lenders but also job-search terminals, tax-help desks, and cooling centers during heat waves. Critics argue that mission creep dilutes the library’s core purpose of literacy. Defenders reply that literacy itself is inseparable from the material conditions that let people read—stable housing, internet access, and time. When a library offers résumé workshops, it is not abandoning books; it is removing barriers that make books unreachable. The sharper debate is fiscal. City budgets treat libraries as discretionary amenities rather than as infrastructure. Infrastructure framing would change maintenance standards, staffing formulas, and resilience planning. A flooded basement that ruins archives is then not a cultural misfortune but a systems failure. Whether councils accept that reframing may determine whether libraries remain open long enough for the literacy mission to matter.", "stem": "The library-as-infrastructure claim is most similar to arguing that:", "choices": ["A) Parks need mowing schedules and flood plans like roads and bridges, not only seasonal festivals", "B) Books should be banned", "C) Only private bookstores matter", "D) Wi-Fi is unnecessary"], "answer": 0, "explain": "Infrastructure = maintenance, standards, resilience—not optional amenity.", "tags": ["high-frequency"]}, {"id": "cars-024", "section": "CARS", "topic": "tone", "difficulty": 2, "passage": "Urban soundscapes are rarely designed; they accumulate. Traffic hum, HVAC drone, and delivery trucks form a baseline that residents stop noticing until illness or remote work forces attention. Noise is not merely annoyance—chronic exposure correlates with cardiovascular stress markers. Zoning that separates industrial and residential uses was partly a noise policy in disguise. As mixed-use density returns, cities rediscover that quiet is a scarce public good. The policy puzzle is distributional: who gets the quiet block, and who gets the freight corridor?", "stem": "The tone of the soundscape passage is best described as:", "choices": ["A) Satirical comedy", "B) Analytical and policy-minded", "C) Celebratory nationalism", "D) Instructional cooking"], "answer": 1, "explain": "Correlates, zoning history, distributional policy puzzle—analytical.", "tags": ["high-frequency"]}, {"id": "cars-025", "section": "CARS", "topic": "detail", "difficulty": 2, "passage": "Historians of technology sometimes overstate discontinuity. The printing press did not instantly create mass literacy; it interacted with paper prices, urban density, religious incentives, and schooling. Likewise, today’s generative models do not automatically produce a new epistemology. They amplify existing incentives: speed over verification, fluency over sourcing, engagement over accuracy. Institutions that already rewarded careful citation may use the tools as drafts to be checked. Institutions that already rewarded volume may use them as substitutes for thought. The machine, in this view, is a mirror with a motor—reflecting norms while accelerating whichever ones are already funded.", "stem": "According to the technology passage, careful-citation institutions may use generative models as:", "choices": ["A) Final unedited publications", "B) Drafts to be checked", "C) Proof that sourcing is obsolete", "D) Reasons to defund libraries"], "answer": 1, "explain": "“drafts to be checked.”", "tags": ["high-frequency"]}, {"id": "bb-001", "section": "BB", "topic": "amino-acids", "difficulty": 1, "passage": null, "stem": "Which amino acid contains a sulfur atom and can form disulfide bridges?", "choices": ["A) Methionine only", "B) Cysteine", "C) Serine", "D) Threonine"], "answer": 1, "explain": "Cysteine’s thiol forms disulfide bonds (cystine). Met has S but does not typically form disulfides.", "tags": ["high-frequency"]}, {"id": "bb-002", "section": "BB", "topic": "amino-acids", "difficulty": 2, "passage": null, "stem": "Essential amino acids must be:", "choices": ["A) Synthesized in adequate amounts by humans", "B) Obtained from diet because humans cannot synthesize them sufficiently", "C) Only aromatic", "D) Negatively charged"], "answer": 1, "explain": "Essential = dietary requirement due to insufficient endogenous synthesis.", "tags": ["high-frequency"]}, {"id": "bb-003", "section": "BB", "topic": "bioenergetics", "difficulty": 2, "passage": null, "stem": "In glycolysis, the net ATP yield per glucose under anaerobic conditions in mammalian cells is typically:", "choices": ["A) 1", "B) 2", "C) 4", "D) 36"], "answer": 1, "explain": "Net 2 ATP (and 2 lactate in anaerobic mammals).", "tags": ["high-frequency", "pathways"]}, {"id": "bb-004", "section": "BB", "topic": "bioenergetics", "difficulty": 3, "passage": null, "stem": "Which step of glycolysis is a major irreversible regulatory point activated by fructose-2,6-bisphosphate in liver?", "choices": ["A) Hexokinase only in all tissues identically", "B) Phosphofructokinase-1 (PFK-1)", "C) Enolase", "D) Phosphoglycerate mutase"], "answer": 1, "explain": "PFK-1 is a key irreversible control point; F2,6BP activates PFK-1.", "tags": ["high-frequency", "pathways"]}, {"id": "bb-005", "section": "BB", "topic": "bioenergetics", "difficulty": 2, "passage": null, "stem": "The citric acid cycle oxidizes acetyl-CoA. Per acetyl-CoA, how many NADH are produced directly by cycle turns (classic count)?", "choices": ["A) 1", "B) 2", "C) 3", "D) 4"], "answer": 2, "explain": "Isocitrate DH, α-KG DH, and malate DH → 3 NADH per acetyl-CoA (plus 1 FADH2 and 1 GTP/ATP).", "tags": ["pathways"]}, {"id": "bb-006", "section": "BB", "topic": "bioenergetics", "difficulty": 3, "passage": null, "stem": "Cyanide inhibits complex IV of the ETC. Immediate expected effect:", "choices": ["A) Increased O2 consumption", "B) Decreased ATP from oxidative phosphorylation; electron flow backs up", "C) Activation of ATP synthase exclusively", "D) Increased proton gradient indefinitely without limit"], "answer": 1, "explain": "Blocking Complex IV stops e− transfer to O2 → OXPHOS ATP falls; upstream carriers reduce.", "tags": ["high-frequency"]}, {"id": "bb-007", "section": "BB", "topic": "genetics", "difficulty": 2, "passage": null, "stem": "In a monohybrid Aa × Aa cross (complete dominance), phenotypic ratio among offspring is typically:", "choices": ["A) 1:1", "B) 3:1", "C) 1:2:1 phenotypic", "D) 9:3:3:1"], "answer": 1, "explain": "Genotypes 1:2:1 but dominant phenotype 3:1.", "tags": ["high-frequency"]}, {"id": "bb-008", "section": "BB", "topic": "genetics", "difficulty": 3, "passage": null, "stem": "A nonsense mutation most directly results in:", "choices": ["A) An amino acid substitution only", "B) Premature stop codon", "C) Silent codon change", "D) Intron retention always"], "answer": 1, "explain": "Nonsense = stop codon created prematurely.", "tags": ["high-frequency"]}, {"id": "bb-009", "section": "BB", "topic": "genetics", "difficulty": 2, "passage": null, "stem": "During DNA replication, Okazaki fragments are synthesized on the:", "choices": ["A) Leading strand continuously", "B) Lagging strand discontinuously", "C) mRNA", "D) Ribosome"], "answer": 1, "explain": "Lagging strand is discontinuous → Okazaki fragments.", "tags": ["high-frequency"]}, {"id": "bb-010", "section": "BB", "topic": "genetics", "difficulty": 3, "passage": null, "stem": "Northern blotting primarily detects:", "choices": ["A) Protein", "B) RNA", "C) Genomic structural variants only by karyotype", "D) Metabolites"], "answer": 1, "explain": "Northern = RNA; Southern = DNA; Western = protein.", "tags": ["lab"]}, {"id": "bb-011", "section": "BB", "topic": "cell-bio", "difficulty": 2, "passage": null, "stem": "Which organelle is the primary site of ATP production via oxidative phosphorylation in eukaryotes?", "choices": ["A) Golgi", "B) Mitochondrion", "C) Lysosome", "D) Peroxisome only"], "answer": 1, "explain": "Mitochondrial inner membrane ETC/OXPHOS.", "tags": ["high-frequency"]}, {"id": "bb-012", "section": "BB", "topic": "cell-bio", "difficulty": 2, "passage": null, "stem": "Rough ER is especially abundant in cells that:", "choices": ["A) Store only glycogen", "B) Secrete large amounts of protein", "C) Lack ribosomes entirely", "D) Perform only β-oxidation"], "answer": 1, "explain": "RER + ribosomes → secreted/membrane protein synthesis.", "tags": ["cell"]}, {"id": "bb-013", "section": "BB", "topic": "cell-bio", "difficulty": 3, "passage": null, "stem": "In G-protein–coupled receptor signaling, activation of Gs typically increases:", "choices": ["A) cAMP via adenylyl cyclase", "B) Only IP3 with no second messengers", "C) Direct DNA ligation", "D) Proteasome assembly exclusively"], "answer": 0, "explain": "Gs → adenylyl cyclase → ↑cAMP → PKA pathway (classic).", "tags": ["high-frequency", "signaling"]}, {"id": "bb-014", "section": "BB", "topic": "physiology", "difficulty": 2, "passage": null, "stem": "Aldosterone primarily promotes in the distal nephron:", "choices": ["A) Na+ reabsorption and K+ secretion", "B) Glucose secretion", "C) Protein filtration increase", "D) ADH antagonism only"], "answer": 0, "explain": "Aldosterone → ENaC/Na/K-ATPase effects: Na+ reabsorb, K+ secrete.", "tags": ["physio", "high-frequency"]}, {"id": "bb-015", "section": "BB", "topic": "physiology", "difficulty": 3, "passage": null, "stem": "During inspiration at rest, alveolar pressure is typically:", "choices": ["A) Above atmospheric", "B) Below atmospheric (air flows in)", "C) Exactly zero absolute vacuum", "D) Unrelated to flow"], "answer": 1, "explain": "Diaphragm descends → thoracic volume ↑ → Palv < Patm → inflow.", "tags": ["physio"]}, {"id": "bb-016", "section": "BB", "topic": "physiology", "difficulty": 2, "passage": null, "stem": "Which blood type is the universal donor for RBC transfusion under standard ABO (ignoring Rh)?", "choices": ["A) AB", "B) A", "C) B", "D) O"], "answer": 3, "explain": "Type O RBCs lack A/B antigens.", "tags": ["physio"]}, {"id": "bb-017", "section": "BB", "topic": "micro", "difficulty": 2, "passage": null, "stem": "Gram-positive bacteria are characterized by:", "choices": ["A) Thin peptidoglycan and outer membrane", "B) Thick peptidoglycan and no outer membrane", "C) No cell wall", "D) Only circular RNA genomes"], "answer": 1, "explain": "Gram+ : thick peptidoglycan, no OM; Gram− : OM + thin PG.", "tags": ["micro"]}, {"id": "bb-018", "section": "BB", "topic": "immune", "difficulty": 2, "passage": null, "stem": "Antibodies are produced by differentiated:", "choices": ["A) Cytotoxic T cells only", "B) B cells / plasma cells", "C) Erythrocytes", "D) Neutrophils exclusively"], "answer": 1, "explain": "Plasma cells (from B cells) secrete antibodies.", "tags": ["high-frequency", "immune"]}, {"id": "bb-019", "section": "BB", "topic": "immune", "difficulty": 3, "passage": null, "stem": "MHC class I presents antigen primarily to:", "choices": ["A) CD4+ helper T cells", "B) CD8+ cytotoxic T cells", "C) B cells only via BCR identical pathway", "D) Basophils only"], "answer": 1, "explain": "MHCI → CD8+ T cells; MHCII → CD4+.", "tags": ["high-frequency"]}, {"id": "bb-020", "section": "BB", "topic": "biochem-pathways", "difficulty": 3, "passage": null, "stem": "β-oxidation of fatty acids occurs primarily in the:", "choices": ["A) Cytosol", "B) Mitochondrial matrix", "C) Nucleus", "D) Golgi lumen"], "answer": 1, "explain": "Mitochondrial matrix (very-long-chain also peroxisomes).", "tags": ["pathways", "high-frequency"]}, {"id": "bb-021", "section": "BB", "topic": "biochem-pathways", "difficulty": 2, "passage": null, "stem": "Insulin promotes which hepatic process?", "choices": ["A) Gluconeogenesis upregulation", "B) Glycogen synthesis", "C) Ketogenesis increase primarily", "D) Hormone-sensitive lipase activation in liver identical to adipocyte fasting"], "answer": 1, "explain": "Insulin → glycogenesis; opposes gluconeogenesis/ketogenesis.", "tags": ["pathways", "high-frequency"]}, {"id": "bb-022", "section": "BB", "topic": "biochem-pathways", "difficulty": 3, "passage": null, "stem": "The pentose phosphate pathway’s oxidative phase uniquely generates:", "choices": ["A) ATP only", "B) NADPH and ribose-5-phosphate precursors", "C) Urea", "D) Lactate exclusively"], "answer": 1, "explain": "Oxidative PPP → NADPH + sugars for nucleotides.", "tags": ["pathways"]}, {"id": "bb-023", "section": "BB", "topic": "genetics", "difficulty": 3, "passage": null, "stem": "X-linked recessive disorders appear more often in males because:", "choices": ["A) Males have two X chromosomes", "B) Males are hemizygous for X-linked genes", "C) Y chromosome encodes all antibodies", "D) Mitochondria are paternal only"], "answer": 1, "explain": "XY hemizygosity: single recessive allele on X is expressed.", "tags": ["genetics", "high-frequency"]}, {"id": "bb-024", "section": "BB", "topic": "lab", "difficulty": 2, "passage": null, "stem": "PCR requires:", "choices": ["A) DNA polymerase, primers, dNTPs, thermal cycling", "B) Only ribosomes", "C) Only restriction enzymes", "D) Antibodies"], "answer": 0, "explain": "Classic PCR components + cycling.", "tags": ["lab"]}, {"id": "bb-025", "section": "BB", "topic": "developmental", "difficulty": 2, "passage": null, "stem": "Gastrulation primarily establishes:", "choices": ["A) Three germ layers", "B) Adult bone marrow only", "C) Fertilization", "D) Lactation"], "answer": 0, "explain": "Ectoderm, mesoderm, endoderm.", "tags": ["dev"]}, {"id": "bb-026", "section": "BB", "topic": "neuro", "difficulty": 2, "passage": null, "stem": "Saltatory conduction occurs along:", "choices": ["A) Unmyelinated C fibers only", "B) Myelinated axons at nodes of Ranvier", "C) Synaptic clefts exclusively", "D) Dendritic spines only"], "answer": 1, "explain": "Action potentials jump between nodes on myelinated axons.", "tags": ["neuro", "high-frequency"]}, {"id": "bb-027", "section": "BB", "topic": "enzyme", "difficulty": 2, "passage": null, "stem": "Competitive inhibitors structurally often resemble:", "choices": ["A) The substrate", "B) The product exclusively always", "C) ATP synthase", "D) Membrane phospholipids only"], "answer": 0, "explain": "Compete at active site → substrate analogs common.", "tags": ["kinetics"]}, {"id": "bb-028", "section": "BB", "topic": "bioenergetics", "difficulty": 4, "passage": null, "stem": "Uncoupling protein activity in brown fat increases heat by:", "choices": ["A) Increasing ATP synthase efficiency", "B) Dissipating proton motive force as heat instead of ATP", "C) Blocking glycolysis", "D) Inhibiting β-oxidation completely"], "answer": 1, "explain": "UCP lets H+ re-enter without ATP synthase → energy as heat.", "tags": ["pathways"]}, {"id": "ps-001", "section": "PS", "topic": "learning", "difficulty": 1, "passage": null, "stem": "In classical conditioning, a neutral stimulus becomes a conditioned stimulus when it reliably predicts:", "choices": ["A) The unconditioned stimulus", "B) Operant reinforcement schedules only", "C) Extinction trials exclusively", "D) Observational models only"], "answer": 0, "explain": "CS comes to predict US; elicits CR.", "tags": ["high-frequency", "classical-conditioning"]}, {"id": "ps-002", "section": "PS", "topic": "learning", "difficulty": 2, "passage": null, "stem": "Extinction in classical conditioning occurs when:", "choices": ["A) CS is presented repeatedly without US", "B) US is intensified", "C) Only positive punishment is used", "D) Modeling increases"], "answer": 0, "explain": "CS alone → CR weakens (extinction).", "tags": ["high-frequency"]}, {"id": "ps-003", "section": "PS", "topic": "learning", "difficulty": 2, "passage": null, "stem": "Variable-ratio schedules of reinforcement typically produce:", "choices": ["A) Rapid extinction and low response rates", "B) High, steady response rates resistant to extinction", "C) No responding", "D) Only classical CRs"], "answer": 1, "explain": "VR (e.g., gambling-like) → high steady rates, extinction-resistant.", "tags": ["operant", "high-frequency"]}, {"id": "ps-004", "section": "PS", "topic": "social", "difficulty": 2, "passage": null, "stem": "Asch’s line studies are classically cited as evidence for:", "choices": ["A) Conformity to group majority judgments", "B) Obedience to authority shocks", "C) Diffusion of responsibility only", "D) Fundamental attribution in juries only"], "answer": 0, "explain": "Asch → conformity; Milgram → obedience. Fix typo in choices.", "tags": ["conformity", "high-frequency"]}, {"id": "ps-005", "section": "PS", "topic": "social", "difficulty": 2, "passage": null, "stem": "Milgram’s obedience studies most directly demonstrated:", "choices": ["A) People never harm others", "B) Ordinary people may obey authority to administer seemingly harmful acts", "C) Conformity to peer dress codes only", "D) Genetic determinism of aggression"], "answer": 1, "explain": "Authority obedience paradigm.", "tags": ["high-frequency", "obedience"]}, {"id": "ps-006", "section": "PS", "topic": "social", "difficulty": 3, "passage": null, "stem": "Diffusion of responsibility helps explain:", "choices": ["A) Why larger groups may reduce individual helping (bystander effect)", "B) Why solitary individuals always help more than any group", "C) Classical conditioning of fear", "D) Sensory adaptation"], "answer": 0, "explain": "Bystander effect / diffusion.", "tags": ["prosocial"]}, {"id": "ps-007", "section": "PS", "topic": "social", "difficulty": 2, "passage": null, "stem": "Fundamental attribution error is the tendency to:", "choices": ["A) Overemphasize dispositional factors for others’ behavior", "B) Always blame the situation for oneself and others equally", "C) Ignore all traits", "D) Prefer statistical base rates only"], "answer": 0, "explain": "Over-attribute others’ actions to personality vs situation.", "tags": ["high-frequency", "attribution"]}, {"id": "ps-008", "section": "PS", "topic": "cognition", "difficulty": 2, "passage": null, "stem": "Working memory’s phonological loop is most associated with temporarily holding:", "choices": ["A) Visual scenes only", "B) Speech-based information", "C) Long-term procedural skills", "D) Olfactory maps only"], "answer": 1, "explain": "Baddeley: phonological loop = verbal/speech-based WM.", "tags": ["memory"]}, {"id": "ps-009", "section": "PS", "topic": "cognition", "difficulty": 3, "passage": null, "stem": "Proactive interference occurs when:", "choices": ["A) Old learning disrupts retrieval of newer learning", "B) New learning disrupts old exclusively as definition of proactive", "C) Encoding never happens", "D) Only sleep causes forgetting"], "answer": 0, "explain": "Proactive: prior info interferes with new; retroactive: new interferes with old.", "tags": ["memory", "high-frequency"]}, {"id": "ps-010", "section": "PS", "topic": "cognition", "difficulty": 2, "passage": null, "stem": "Heuristic that judges probability by resemblance to a prototype:", "choices": ["A) Availability", "B) Representativeness", "C) Anchoring only", "D) Confirmation exclusively"], "answer": 1, "explain": "Representativeness heuristic.", "tags": ["high-frequency"]}, {"id": "ps-011", "section": "PS", "topic": "development", "difficulty": 2, "passage": null, "stem": "Piaget’s stage associated with abstract hypothetical reasoning:", "choices": ["A) Sensorimotor", "B) Preoperational", "C) Concrete operational", "D) Formal operational"], "answer": 3, "explain": "Formal operational → abstract/hypothetical.", "tags": ["dev", "high-frequency"]}, {"id": "ps-012", "section": "PS", "topic": "development", "difficulty": 2, "passage": null, "stem": "Erikson’s stage for adolescents centers on:", "choices": ["A) Trust vs mistrust", "B) Identity vs role confusion", "C) Integrity vs despair", "D) Generativity vs stagnation"], "answer": 1, "explain": "Adolescence: identity vs role confusion.", "tags": ["dev"]}, {"id": "ps-013", "section": "PS", "topic": "biological", "difficulty": 2, "passage": null, "stem": "The neurotransmitter most associated with reward pathways and certain motor control is:", "choices": ["A) Dopamine", "B) GABA as sole excitatory transmitter", "C) Only glycine in cortex", "D) Melatonin for fast EPSPs"], "answer": 0, "explain": "Dopamine: reward, movement (nigrostriatal).", "tags": ["neuro", "high-frequency"]}, {"id": "ps-014", "section": "PS", "topic": "biological", "difficulty": 3, "passage": null, "stem": "Broca’s aphasia is typically associated with impaired:", "choices": ["A) Speech production with relatively spared comprehension", "B) Only face recognition", "C) Hearing pure tones only", "D) Spinal reflexes"], "answer": 0, "explain": "Broca (frontal) production; Wernicke comprehension.", "tags": ["neuro", "high-frequency"]}, {"id": "ps-015", "section": "PS", "topic": "biological", "difficulty": 2, "passage": null, "stem": "Sympathetic nervous system activation generally:", "choices": ["A) Decreases heart rate and dilates pupils never", "B) Increases heart rate and mobilizes energy (fight-or-flight)", "C) Only promotes digestion", "D) Is identical to parasympathetic effects"], "answer": 1, "explain": "Sympathetic: fight-or-flight.", "tags": ["physio-psych"]}, {"id": "ps-016", "section": "PS", "topic": "sensation", "difficulty": 2, "passage": null, "stem": "Absolute threshold is:", "choices": ["A) Smallest detectable stimulus intensity ~50% of the time", "B) Difference between two stimuli only", "C) Maximum pain tolerance always", "D) Weber’s constant exclusively"], "answer": 0, "explain": "Absolute threshold definition; difference threshold = JND.", "tags": ["sensation"]}, {"id": "ps-017", "section": "PS", "topic": "sensation", "difficulty": 3, "passage": null, "stem": "Weber’s law states that JND is:", "choices": ["A) A constant proportion of stimulus intensity", "B) A fixed absolute amount for all senses always", "C) Independent of stimulus magnitude", "D) Only about vision"], "answer": 0, "explain": "ΔI/I ≈ constant.", "tags": ["sensation", "high-frequency"]}, {"id": "ps-018", "section": "PS", "topic": "psych-disorders", "difficulty": 2, "passage": null, "stem": "Positive symptoms of schizophrenia include:", "choices": ["A) Flat affect only", "B) Hallucinations and delusions", "C) Anhedonia exclusively as definition of positive", "D) Only memory loss"], "answer": 1, "explain": "Positive = added experiences (hallucinations/delusions); negative = deficits.", "tags": ["high-frequency"]}, {"id": "ps-019", "section": "PS", "topic": "psych-disorders", "difficulty": 2, "passage": null, "stem": "SSRIs primarily increase synaptic availability of:", "choices": ["A) Serotonin", "B) Only acetylcholine", "C) Histamine exclusively", "D) Nitric oxide as neurotransmitter of SSRIs"], "answer": 0, "explain": "Selective serotonin reuptake inhibitors.", "tags": ["treatment"]}, {"id": "ps-020", "section": "PS", "topic": "social-structure", "difficulty": 2, "passage": null, "stem": "Socioeconomic status (SES) is commonly indexed by:", "choices": ["A) Income, education, and occupation", "B) Only eye color", "C) Only resting heart rate", "D) Blood type"], "answer": 0, "explain": "Classic SES indicators.", "tags": ["SES", "high-frequency"]}, {"id": "ps-021", "section": "PS", "topic": "social-structure", "difficulty": 3, "passage": null, "stem": "The social gradient in health refers to:", "choices": ["A) Better average health with higher SES across the ladder", "B) Identical health at all incomes", "C) Only genetic disease", "D) Random noise without pattern"], "answer": 0, "explain": "Health improves stepwise with SES—not only poverty vs non-poverty.", "tags": ["SES", "health", "high-frequency"]}, {"id": "ps-022", "section": "PS", "topic": "social-structure", "difficulty": 2, "passage": null, "stem": "Cultural capital (Bourdieu) most nearly includes:", "choices": ["A) Embodied skills, tastes, and credentials that confer advantage", "B) Only cash in a wallet", "C) Only military rank", "D) Blood glucose"], "answer": 0, "explain": "Non-financial cultural assets.", "tags": ["sociology"]}, {"id": "ps-023", "section": "PS", "topic": "social", "difficulty": 3, "passage": null, "stem": "Stereotype threat research suggests that reminding a stigmatized group of a negative stereotype can:", "choices": ["A) Impair performance in the stereotyped domain", "B) Always improve scores", "C) Eliminate anxiety", "D) Change DNA sequence"], "answer": 0, "explain": "Stereotype threat → performance decrements.", "tags": ["high-frequency"]}, {"id": "ps-024", "section": "PS", "topic": "demographics", "difficulty": 2, "passage": null, "stem": "Incidence rate measures:", "choices": ["A) New cases in a population over time", "B) All existing cases at a snapshot only (that is prevalence)", "C) Only case fatality", "D) Only birth rate"], "answer": 0, "explain": "Incidence = new; prevalence = existing.", "tags": ["epi", "high-frequency"]}, {"id": "ps-025", "section": "PS", "topic": "demographics", "difficulty": 2, "passage": null, "stem": "Prevalence can remain high while incidence falls if:", "choices": ["A) Disease duration lengthens (e.g., better chronic management)", "B) Everyone dies instantly", "C) No one ever gets the disease", "D) Definitions never change and duration is zero"], "answer": 0, "explain": "Prevalence ≈ incidence × duration.", "tags": ["epi"]}, {"id": "ps-026", "section": "PS", "topic": "personality", "difficulty": 2, "passage": null, "stem": "The Big Five trait “conscientiousness” most involves:", "choices": ["A) Orderliness, responsibility, self-discipline", "B) Only sociability", "C) Only emotional volatility", "D) Openness to fantasy exclusively"], "answer": 0, "explain": "Conscientiousness facet cluster.", "tags": ["personality"]}, {"id": "ps-027", "section": "PS", "topic": "motivation", "difficulty": 2, "passage": null, "stem": "Drive-reduction theories emphasize that motivation often arises to:", "choices": ["A) Reduce physiological tension and return toward homeostasis", "B) Maximize novelty only", "C) Ignore needs", "D) Only seek extrinsic trophies"], "answer": 0, "explain": "Classic drive reduction / homeostasis.", "tags": ["motivation"]}, {"id": "ps-028", "section": "PS", "topic": "social", "difficulty": 2, "passage": null, "stem": "Groupthink is most likely when a cohesive group:", "choices": ["A) Prioritizes consensus over critical evaluation", "B) Encourages devil’s advocates always", "C) Has no leader", "D) Uses only anonymous voting with dissent rewards"], "answer": 0, "explain": "Consensus pressure → poor decisions.", "tags": ["group-processes", "high-frequency"]}, {"id": "cp-029", "section": "CP", "topic": "acids-bases", "difficulty": 3, "passage": null, "stem": "For a weak acid HA with Ka = 1×10−5, the pKa is:", "choices": ["A) 5", "B) −5", "C) 9", "D) 1×10−5"], "answer": 0, "explain": "pKa = −log Ka = 5.", "tags": ["acids"]}, {"id": "cp-030", "section": "CP", "topic": "gases", "difficulty": 2, "passage": null, "stem": "At constant T and n, Boyle’s law states PV is:", "choices": ["A) Constant", "B) Proportional to T only in Boyle", "C) Zero", "D) Proportional to n^2"], "answer": 0, "explain": "PV = const at fixed T,n.", "tags": ["gases"]}, {"id": "bb-029", "section": "BB", "topic": "genetics", "difficulty": 2, "passage": null, "stem": "Crossing over during meiosis occurs in:", "choices": ["A) Prophase I", "B) Metaphase II only", "C) Telophase of mitosis", "D) G0 exclusively"], "answer": 0, "explain": "Recombination in prophase I (synapsis).", "tags": ["meiosis"]}, {"id": "bb-030", "section": "BB", "topic": "physiology", "difficulty": 3, "passage": null, "stem": "ADH (vasopressin) increases water reabsorption primarily in the:", "choices": ["A) Collecting duct via aquaporins", "B) Bowman’s capsule filtration slits only", "C) Proximal tubule exclusively without receptors", "D) Ureter smooth muscle as primary site"], "answer": 0, "explain": "ADH → AQP2 in collecting duct.", "tags": ["physio", "high-frequency"]}, {"id": "ps-029", "section": "PS", "topic": "learning", "difficulty": 3, "passage": null, "stem": "Shaping in operant conditioning involves:", "choices": ["A) Reinforcing successive approximations of a target behavior", "B) Only classical pairing", "C) Punishing all behavior randomly", "D) Extinction without reinforcement history"], "answer": 0, "explain": "Successive approximations.", "tags": ["operant"]}, {"id": "ps-030", "section": "PS", "topic": "social", "difficulty": 2, "passage": null, "stem": "In-group favoritism most nearly means:", "choices": ["A) Preferential treatment of one’s own group", "B) Always hating all out-groups identically by definition", "C) Random allocation", "D) Ignoring group identity"], "answer": 0, "explain": "Preferential evaluation/treatment of in-group.", "tags": ["social-identity"]}, {"id": "cars-026", "section": "CARS", "topic": "detail", "difficulty": 2, "passage": "Municipal libraries have quietly become hybrid civic hubs: not only book lenders but also job-search terminals, tax-help desks, and cooling centers during heat waves. Critics argue that mission creep dilutes the library’s core purpose of literacy. Defenders reply that literacy itself is inseparable from the material conditions that let people read—stable housing, internet access, and time. When a library offers résumé workshops, it is not abandoning books; it is removing barriers that make books unreachable. The sharper debate is fiscal. City budgets treat libraries as discretionary amenities rather than as infrastructure. Infrastructure framing would change maintenance standards, staffing formulas, and resilience planning. A flooded basement that ruins archives is then not a cultural misfortune but a systems failure. Whether councils accept that reframing may determine whether libraries remain open long enough for the literacy mission to matter.", "stem": "The library passage states city budgets often treat libraries as:", "choices": ["A) Discretionary amenities", "B) Mandatory hospitals", "C) Military bases", "D) Private equity firms"], "answer": 0, "explain": "“discretionary amenities rather than as infrastructure.”", "tags": ["high-frequency"]}, {"id": "cars-027", "section": "CARS", "topic": "inference", "difficulty": 3, "passage": "Municipal libraries have quietly become hybrid civic hubs: not only book lenders but also job-search terminals, tax-help desks, and cooling centers during heat waves. Critics argue that mission creep dilutes the library’s core purpose of literacy. Defenders reply that literacy itself is inseparable from the material conditions that let people read—stable housing, internet access, and time. When a library offers résumé workshops, it is not abandoning books; it is removing barriers that make books unreachable. The sharper debate is fiscal. City budgets treat libraries as discretionary amenities rather than as infrastructure. Infrastructure framing would change maintenance standards, staffing formulas, and resilience planning. A flooded basement that ruins archives is then not a cultural misfortune but a systems failure. Whether councils accept that reframing may determine whether libraries remain open long enough for the literacy mission to matter.", "stem": "If councils accept infrastructure framing, the author suggests libraries may:", "choices": ["A) Gain maintenance standards and resilience planning that support literacy goals", "B) Immediately become for-profit", "C) Stop offering books", "D) Avoid staffing formulas"], "answer": 0, "explain": "Infrastructure framing → standards/staffing/resilience; open long enough for literacy.", "tags": ["high-frequency"]}, {"id": "cp-031", "section": "CP", "topic": "optics", "difficulty": 3, "passage": null, "stem": "Total internal reflection requires light in a higher-n medium incident above critical angle toward lower-n. Critical angle satisfies:", "choices": ["A) sin θc = n2/n1 (n1>n2)", "B) sin θc = n1/n2", "C) θc = 90° always", "D) θc = 0°"], "answer": 0, "explain": "sin θc = n_low/n_high.", "tags": ["optics"]}, {"id": "bb-031", "section": "BB", "topic": "immune", "difficulty": 2, "passage": null, "stem": "Vaccines primarily train:", "choices": ["A) Adaptive immunity (memory B/T responses)", "B) Only bone density", "C) Digestion", "D) Hair growth"], "answer": 0, "explain": "Adaptive memory.", "tags": ["immune", "high-frequency"]}, {"id": "ps-031", "section": "PS", "topic": "cognition", "difficulty": 2, "passage": null, "stem": "Confirmation bias is the tendency to:", "choices": ["A) Seek and favor information that supports existing beliefs", "B) Always falsify hypotheses carefully", "C) Ignore all evidence", "D) Prefer only base rates"], "answer": 0, "explain": "Confirming evidence preferred.", "tags": ["high-frequency"]}, {"id": "bb-032", "section": "BB", "topic": "cell-bio", "difficulty": 3, "passage": null, "stem": "Apoptosis is:", "choices": ["A) Programmed cell death", "B) Uncontrolled necrosis only by definition", "C) Mitosis", "D) Meiosis II"], "answer": 0, "explain": "Programmed cell death.", "tags": ["cell"]}, {"id": "cp-032", "section": "CP", "topic": "equilibrium", "difficulty": 2, "passage": null, "stem": "Adding a catalyst to a reversible reaction at equilibrium:", "choices": ["A) Changes Keq", "B) Speeds both forward and reverse rates; Keq unchanged", "C) Only speeds forward permanently shifting K", "D) Stops the reverse reaction"], "answer": 1, "explain": "Catalysts don’t change ΔG° or Keq; accelerate both directions.", "tags": ["equilibrium", "high-frequency"]}, {"id": "ps-032", "section": "PS", "topic": "biological", "difficulty": 2, "passage": null, "stem": "The hippocampus is especially associated with:", "choices": ["A) Formation of new declarative memories", "B) Only spinal reflexes", "C) Only visual edge detection in V1 exclusively", "D) Liver metabolism"], "answer": 0, "explain": "Hippocampus / medial temporal lobe memory encoding.", "tags": ["neuro", "high-frequency"]}, {"id": "cars-028", "section": "CARS", "topic": "vocab", "difficulty": 2, "passage": "Historians of technology sometimes overstate discontinuity. The printing press did not instantly create mass literacy; it interacted with paper prices, urban density, religious incentives, and schooling. Likewise, today’s generative models do not automatically produce a new epistemology. They amplify existing incentives: speed over verification, fluency over sourcing, engagement over accuracy. Institutions that already rewarded careful citation may use the tools as drafts to be checked. Institutions that already rewarded volume may use them as substitutes for thought. The machine, in this view, is a mirror with a motor—reflecting norms while accelerating whichever ones are already funded.", "stem": "In context, “epistemology” in the technology passage most nearly means:", "choices": ["A) Theory of knowledge / how we know", "B) Study of insects", "C) Tax policy", "D) Bridge engineering"], "answer": 0, "explain": "Epistemology = knowledge theory; models don’t auto-create a new one.", "tags": ["high-frequency"]}]};
